-- Retail Transactions Dataset
CREATE DATABASE IF NOT EXISTS retail_sales;
USE retail_sales;

DROP TABLE IF EXISTS retail_transactions_db;

CREATE TABLE retail_transactions_db (
    TransactionID VARCHAR(20),
    Date DATETIME,
    ProductName VARCHAR(100),
    Category VARCHAR(100),
    Region VARCHAR(50),
    SalesChannel VARCHAR(30),
    Quantity INT,
    UnitPrice DOUBLE,
    TotalAmount DOUBLE,
    PaymentMode VARCHAR(50),
    CustomerID VARCHAR(30)
);

